import sys
sys.setrecursionlimit(10000)

def neighbors(c):
    r,col=divmod(c,8)
    res=[]
    for dr,dc in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
        nr,nc=r+dr,col+dc
        if 0<=nr<8 and 0<=nc<8:
            res.append(nr*8+nc)
    return res

N=[neighbors(i) for i in range(64)]

fixed={0:0,2:27,3:21,10:16,11:1,19:24,21:3,27:51,38:38,50:43,51:60,59:53,61:42}

# check fixed consistency: consecutive steps must be knight moves
for i in range(63):
    if i in fixed and (i+1) in fixed:
        if fixed[i+1] not in N[fixed[i]]:
            print("INCONSISTENT",i,fixed[i],fixed[i+1])

path=[-1]*64
used=[False]*64
for i,v in fixed.items():
    path[i]=v
    used[v]=True

def solve(step):
    if step==64: return True
    if path[step]!=-1:
        # check move from prev
        if step>0 and path[step-1]!=-1:
            if path[step] not in N[path[step-1]]:
                return False
        return solve(step+1)
    prev=path[step-1]
    # Warnsdorff-like ordering
    cands=[c for c in N[prev] if not used[c]]
    # if next step fixed, must move to it
    nxt=path[step+1] if step+1<64 else -1
    def score(c):
        s=sum(1 for x in N[c] if not used[x])
        return s
    cands.sort(key=score)
    for c in cands:
        if nxt!=-1 and c!=nxt and nxt not in N[c]:
            continue
        path[step]=c
        used[c]=True
        if solve(step+1):
            return True
        used[c]=False
        path[step]=-1
    return False

import time
t=time.time()
ok=solve(1)
print(ok,time.time()-t)
if ok: print(path)
